export const pt={"lang.label":"Idioma","lang.auto":"GUI do sistema","nav.settings":"Definições","nav.storage":"Armazenamento","nav.help":"Ajuda","nav.activation":"Ativação","nav.about":"Sobre","hud.copy.scope":"Copiar âmbito, versão, versão VS, derivado e projeto","hud.copy.scope.done":"Copiado","hud.copy.field.scope":"Âmbito","hud.copy.field.project":"Projeto","hud.copy.field.version":"Versão","hud.copy.field.derivative":"Derivado","hud.copy.field.variation":"Variante do VS Code","hud.copy.field.vsVersion":"Versão do VS Code","hud.copy.field.content":"Conteúdo","hud.copy.edit.project":"projeto","settings.scope":"Âmbito:","settings.scope.project":"Projeto (predefinição)","settings.scope.hint.project":"Edição: projeto Agents atual (âmbito Projeto)","settings.scope.hint.global":"Edição: Global (fallback sem override de projeto)","pill.scope":"Âmbito:","settings.size":"Tamanho:","settings.style":"Estilo:","settings.style.stripes":"Riscas","settings.lookPreset":"Predefinição look","settings.reset":"Repor","settings.apply":"Aplicar","settings.close":"Fechar","settings.boxModel":"Modelo de caixa (clique = camada)","settings.inspector.border":"Inspetor — Borda","settings.inspector.border.purpose":"O anel colorido do modelo de caixa é a moldura da pill. Cor e espessura aplicam-se após Aplicar.","settings.inspector.margin.purpose":"A margem externa é o espaço fora da moldura.","settings.inspector.padding.purpose":"A margem interna é o espaço dentro da moldura, à volta da etiqueta.","settings.inspector.content.purpose":"O conteúdo é a etiqueta: tipo de letra, preenchimento e cor do texto.","settings.inspector.margin":"Inspetor — Margem externa","settings.inspector.padding":"Inspetor — Margem interna","settings.inspector.content":"Inspetor — Conteúdo","settings.inspector.preset":"Inspetor — Cor e forma","settings.borderColor":"Cor da borda","settings.borderWidth":"Largura da borda","settings.margin":"Margem externa (Margin)","settings.padding":"Margem interna (Padding)","settings.font":"Tipo de letra","settings.fontSize":"Tamanho da letra","settings.fill":"Cor de preenchimento","settings.textColor":"Cor do texto","settings.iconTitle":"Ícone / Padrão","settings.mode":"Modo:","settings.iconColor":"Cor do ícone:","settings.pattern":"Padrão:","settings.logo":"Logo personalizado:","settings.logo.browse":"Procurar…","settings.logo.hint.empty":"Sem logo personalizado — opcional via Procurar…","settings.logo.hint.custom":"Logo personalizado ativo","settings.logo.hint.repo":"O logo fica no repositório do projeto — atualizações do ficheiro aparecem na pill.","settings.logo.hint.orb":"Orbe de predefinição ativo (sem caminho de ficheiro)","settings.prefs.export":"Exportar prefs","settings.prefs.import":"Importar prefs","settings.profile.save":"Guardar perfil","settings.profile.load":"Carregar perfil","settings.prefs.vsProfile":"Exportar e Importar movem um ficheiro. Guardar e Carregar perfil guardam uma cópia com nome na pasta de perfis e contam para o limite. Apply põe-na na pill.","settings.prefs.loaded":"Carregado {name}. Está neste diálogo (âmbito: {scope}). Apply põe-no na pill.","settings.autostart":"Iniciar o HUD com o Windows","settings.zebra.consent":"Permitir acesso à rede para procurar atualizações (pode ser desativado a qualquer momento).","settings.pro.line":"Trial/Pro: Padrão / Logo / Prefs — Logos {logos}/{logoMax} · Perfis {profiles}/{profMax} — ready-4-it.com/akc_ccc","settings.theme.hint":"Cor e forma são separadas. Pastel, Metal, Studio e Néon valem cada uma com Nenhuma, cubo, texto, vidro ou esfera. Ícone/logo inalterado. A pill só atualiza após Aplicar.","settings.theme.bgTitle":"Fundo (orbe → logo)","settings.theme.bgHint":"Substitui o ícone/logo — ação separada das cores look.","storage.title":"Armazenamento / Memória","storage.sub":"Base de dados local de conversas do Cursor (state.vscdb). Apenas leitura do tamanho — nunca é alterada com o Cursor aberto. Cópia e compactação exigem o Cursor totalmente fechado.","storage.dbPath":"Caminho da base de dados","storage.sizeLabel":"Tamanho: {size}","storage.sizeMissing":"Ficheiro da base de dados não encontrado","storage.warnMb":"Limite de aviso (MB)","storage.warnOver":"Acima do limite de aviso ({mb} MB) — considere compactar offline depois de fechar o Cursor.","storage.warnOk":"Abaixo do limite de aviso ({mb} MB).","storage.softCap":"Limite flexível da sessão (para a futura memória MCP)","storage.archiveDir":"Pasta de arquivo / cópia (vazio = ~/.cursor-archive)","storage.browse":"Procurar…","storage.mcpEnable":"Ativar memória MCP (preferência)","storage.mcpHint":"Trial/Pro: ativa a memória MCP local (archive_session_chunk). Free/Public: apenas tamanho do armazenamento e arquivos recentes.","storage.mcp.proOnly":"A memória MCP requer Trial/Pro (ativado). Abra ready-4-it.com/akc_ccc para atualizar.","storage.refresh":"Atualizar tamanho","storage.backup":"Cópia de segurança agora","storage.compact":"Compactar offline…","storage.compact.confirm":"Isto limpa entradas grandes de cache e reduz a base de dados. O Cursor tem de permanecer completamente fechado. Continuar?","storage.apply":"Guardar prefs","storage.openHelp":"Abrir tópico de ajuda","storage.saved":"Prefs de armazenamento guardadas.","storage.status.cursorRunning":"O Cursor está em execução — feche-o por completo antes da cópia de segurança ou da compactação offline.","storage.status.cursorQuit":"Cursor não detetado — cópia de segurança / compactação offline podem ser executadas.","storage.busy.backup":"A fazer cópia de segurança…","storage.busy.compact":"A compactar offline (pode demorar minutos em bases grandes)…","storage.ok.backup":"Cópia de segurança concluída.","storage.ok.compact":"Compactação offline concluída. Reinicie o Cursor quando quiser.","storage.err.helpers":"Faltam ficheiros auxiliares de armazenamento. Reinstale o plugin.","storage.err.cursorRunning":"Feche primeiro o Cursor por completo (todos os processos) e tente novamente.","storage.err.exit":"O script de manutenção terminou com o código {code}. Veja a janela do PowerShell para detalhes.","storage.archives.title":"Arquivos CCC (só leitura)","storage.archives.sub":"Pesquisa em CCC agent_memory.db — não o Unarchive da barra Cursor/VS Code. Ative primeiro MCP Memory e archive chunks. Restaurar continua a ser função do anfitrião.","storage.archives.recent":"Recentes","storage.archives.search":"Pesquisar","storage.archives.searchPro":"A pesquisa de arquivos é Trial/Pro. A abrir ready-4-it.com/akc_ccc — Free mantém só uma lista Recentes curta.","storage.archives.empty":"Ainda sem arquivos CCC. Ative MCP Memory, depois archive_session_chunk / resumos.","storage.archives.missing":"Falta o visualizador de arquivos. Reinstale o plugin.","storage.archives.note":"{count} entrada(s) · {path}","storage.archives.hint":"Índice CCC só de leitura. Unarchive do anfitrião: barra Agents → filtro Arquivado → Unarchive.","storage.quiet.title":"Silêncio / suspensão (deploy e E/S intensiva)","storage.quiet.sub":"Com o Silêncio ativo, o HUD pausa as consultas de identidade às bases do Cursor/VS Code, para que escrever no Agents continue fluido durante deploys ou sincronizações pesadas. A pill mostra o silêncio com um temporizador.","storage.quiet.enabled":"Ativar regras de Silêncio","storage.quiet.auto":"Suspensão automática quando as leituras do HUD continuam lentas (opcional — pode aumentar a carga)","storage.quiet.defaultSleep":"Suspensão predefinida (segundos)","storage.quiet.rules":"Regras (uma por linha: nome=segundos)","storage.quiet.hint":"Exemplos: deploy.exe=300  ou  deploy.ps1=300  ou  WinSCP.exe=180\nA correspondência é pelo nome do processo (deploy.exe) ou por uma subcadeia da linha de comandos apenas entre powershell/pwsh/cmd (deploy.ps1). Não pelo título da janela. Deixe a suspensão automática desativada se não for necessária. Prefs: %USERPROFILE%\\.cursor\\ccc-hud-quiet-prefs.json","storage.exp.title":"Experiências (opcional)","storage.exp.sub":"Desativado por predefinição = pill estável como antes. As novas funções (watch, silêncio, UIA, base glass) só quando quiser testar — podem causar engasgos no ambiente de trabalho.","storage.exp.enabled":"Desbloquear experiências","storage.exp.hudWatch":"HUD watch (seguir a identidade)","storage.exp.quiet":"Regras de Silêncio / suspensão","storage.exp.uia":"Análise UIA da barra lateral (VS Code)","storage.exp.glass":"Leituras Glass / state.vscdb","storage.exp.hint":"Após alterações: reinicie o HUD (Stop → Start). Prefs: %USERPROFILE%\\.cursor\\ccc-hud-experiments.json","storage.tab.main":"Armazenamento","storage.tab.bak":"Cópia","storage.tab.ext":"Alargado","storage.bak.title":"Prefs, perfis e logo","storage.bak.sub":"Exportar e Importar movem um JSON para onde quiser. Guardar e Carregar perfil mantêm um instantâneo com nome na pasta de perfis e contam para o limite. O ficheiro do logo é escrito junto a esse JSON e reposto com ele. Aplicar continua a escrever o aspeto na pill.","storage.help.bak.goal.title":"O que é guardado","storage.help.bak.goal.body":"O JSON guarda cores, forma e o caminho do logo. A imagem em si é o ficheiro .logo junto ao JSON. Os orbs (Pastell, Metall, 3D, Neon) são repostos a partir desse ficheiro, ou da arte integrada se a cópia faltar.","storage.ext.title":"Alargado (MCP e manutenção)","storage.ext.sub":"Preferência de memória MCP (Trial/Pro), cópia de segurança e compactação offline do Cursor state.vscdb — só com o Cursor totalmente fechado.","storage.help.close":"Fechar","storage.help.toggle":"Ajuda","storage.help.empty":"Ainda não há texto de ajuda para este separador.","storage.ext.recommend":"Dica: feche o Cursor por completo antes da cópia de segurança ou da compactação offline. Observe a linha de estado abaixo dos botões.","storage.help.main":"state.vscdb guarda os dados de chat do Agents. Aqui: ler o tamanho, definir o limite de aviso e o limite flexível, escolher a pasta de arquivo, percorrer os arquivos de sessão.\n\nPrefs: %USERPROFILE%\\.cursor\\ccc-memory-prefs.json\n\nCópia e compactação estão em Alargado — feche primeiro o Cursor.","storage.help.exp":"As experiências estão desativadas por predefinição (pill estável).\n\nDesbloqueie o interruptor geral e ative: HUD watch, Silêncio, UIA, base glass.\nAs regras de Silêncio (deploy.exe=300) pausam as consultas de identidade.\n\nPrefs: ccc-hud-experiments.json e ccc-hud-quiet-prefs.json em %USERPROFILE%\\.cursor\\\nApós guardar: HUD Stop → Start.","storage.help.ext":"Memória MCP (Trial/Pro): preferência para a memória local de sessão.\n\nCópia de segurança: copia state.vscdb para a pasta de arquivo — só com o Cursor fechado.\n\nCompactar offline: reduz a base depois de fechar o Cursor.\n\nNunca compacte com o Cursor aberto.","storage.help.main.goal.title":"O que este separador faz","storage.help.main.goal.body":"Ler o tamanho de state.vscdb, definir o limite de aviso e o limite flexível, escolher a pasta de arquivo e percorrer os arquivos de sessão do CCC. Nunca compacte com o Cursor aberto.","storage.help.main.defaults.title":"Predefinições","storage.help.main.defaults.body":"Limite de aviso: 2048 MB\nLimite flexível: 40 (futura memória MCP)\nPasta de arquivo: ~/.cursor-archive se vazio\nMemória MCP: desativada (preferência Trial/Pro)\nPrefs: %USERPROFILE%\\.cursor\\ccc-memory-prefs.json","storage.help.main.do.title":"Utilização diária","storage.help.main.do.body":"Atualize o tamanho de vez em quando.\nGuarde as prefs após alterações.\nUse os arquivos recentes (Free: lista curta; Pro: pesquisa).\nCópia e compactação estão em Alargado — feche primeiro o Cursor.","storage.help.main.critical.title":"Quando algo parece bloqueado","storage.help.main.critical.body":"Base muito acima do aviso + Agents bloqueia → separador Alargado.\nO ambiente de trabalho engasga por causa do HUD → separador Experimental, desative Silêncio/UIA, HUD Stop → Start.","storage.help.main.steps.title":"Compactação offline (Alargado)","storage.help.main.steps.body":"1) Feche o Cursor (área de notificação, até não restar Cursor.exe)\n2) Alargado → Compactar offline\n3) Reinicie o Cursor no fim","storage.help.exp.goal.title":"O que são as experiências","storage.help.exp.goal.body":"Watch + Glass mantêm a pill no projeto Agents certo (ativado por predefinição).\nSilêncio e UIA são os interruptores arriscados — ative-os só de propósito.","storage.help.exp.defaults.title":"Predefinições","storage.help.exp.defaults.body":"Interruptor geral das experiências: desativado\nWatch + Glass: ativados (identidade)\nSilêncio + UIA: desativados\nFicheiros: ccc-hud-experiments.json, ccc-hud-quiet-prefs.json","storage.help.exp.do.title":"Quando mexer nisto","storage.help.exp.do.body":"Uso diário: deixe o interruptor geral desativado — Watch/Glass continuam a funcionar.\nSilêncio só com regras concretas (p. ex. deploy.exe=300).\nUIA só por pouco tempo — muitas vezes bloqueia o ambiente de trabalho.","storage.help.exp.critical.title":"Se o IDE engasgar","storage.help.exp.critical.body":"O IDE engasga com o HUD → desative Silêncio/UIA, guarde as prefs, HUD Stop → Start.\nDeixe a suspensão automática do Silêncio desativada — ela própria aumenta a carga.","storage.help.exp.steps.title":"Após alterações","storage.help.exp.steps.body":"Guarde as prefs no separador.\nHUD Stop → Start.","storage.help.ext.goal.title":"Alargado / manutenção","storage.help.ext.goal.body":"Preferência de memória MCP (Trial/Pro), cópia de segurança e compactação offline de state.vscdb — só com o Cursor totalmente fechado.","storage.help.ext.defaults.title":"Regras de segurança","storage.help.ext.defaults.body":"A cópia de segurança guarda state.vscdb na sua pasta de arquivo.\nA compactação offline reduz a base de conversas.\nO CCC recusa ambas enquanto houver um processo do Cursor em execução.","storage.help.ext.do.title":"Fluxo recomendado","storage.help.ext.do.body":"Verifique a linha de estado (em execução ou fechado).\nFaça primeiro a cópia quando a base for enorme.\nCompacte só depois de fechar; pode demorar minutos.\nReinicie o Cursor após compactar.","storage.help.ext.critical.title":"Nunca faça isto","storage.help.ext.critical.body":"Nunca compacte com o Cursor aberto — isso pode danificar a base de dados de conversas.","storage.help.ext.steps.title":"Passos da compactação","storage.help.ext.steps.body":"1) Feche o Cursor por completo\n2) Alargado → Compactar offline → confirmar\n3) Aguarde o estado OK\n4) Inicie o Cursor novamente","help.nav":"Tópicos","help.drawer.toggle":"Ajuda","help.drawer.tip":"Ajuda desta página","help.drawer.close":"Fechar","help.drawer.openTopic":"Abrir na Ajuda","help.drawer.look.title":"Aspeto","help.drawer.look.body":"O modelo de caixa é o esboço das camadas. A pré-visualização mini é a pill. Cor e forma escolhem-se aqui, e Aplicar escreve-as na pill. Ícone e logo são o outro controlo das Definições.","help.drawer.logo.title":"Ícone e logo","help.drawer.logo.body":"Pastell, Metall, 3D e Neon substituem o ícone. Um logo próprio mantém-se enquanto não marcar substituir. A exportação e os perfis em Armazenamento → Cópia guardam o ficheiro do logo junto ao JSON.","help.drawer.storage.title":"Armazenamento do Cursor","help.drawer.storage.body":"state.vscdb guarda os dados de chat do Agents. Este separador lê o tamanho, o limite de aviso e a pasta de arquivo. Copiar ou compactar essa base está em Alargado, e só depois de fechar o Cursor.","help.drawer.backup.title":"Prefs e perfis","help.drawer.backup.body":"Exportar move um ficheiro JSON para onde escolher. Guardar perfil mantém uma cópia com nome na pasta de perfis e conta para o limite. O ficheiro do logo é escrito junto ao JSON e volta ao importar ou carregar.","help.drawer.experiments.title":"Experiências","help.drawer.experiments.body":"Watch e Glass mantêm a pill no chat do Agents selecionado. Silêncio e UIA ficam desativados, a menos que os ative. Após uma alteração, pare o HUD e inicie-o de novo.","help.drawer.hygiene.title":"Cópia de segurança da base","help.drawer.hygiene.body":"Cópia de segurança agora copia state.vscdb. Compactar offline reduz a base. Ambas só funcionam com o Cursor completamente fechado.","help.drawer.activate.title":"De Free para Pro","help.drawer.activate.body":"Obtenha o CCC Pro em ready-4-it.com/akc_ccc, instale o pacote licenciado e ative aqui com o hash do dispositivo e o token R4IT….","help.drawer.about.title":"Atualizações","help.drawer.about.body":"Clique em Procurar atualizações para transferir e instalar diretamente uma nova versão. Na primeira vez, o HUD pede a sua autorização uma única vez.","help.topic.overview.title":"Visão geral","help.topic.overview.nav":"Visão geral","help.topic.overview.body":"O AI Keep Clean Context Control Center (CCC) dá a cada projeto no Cursor e no VS Code uma identidade visual imediata.\n\nA Pill flutuante na margem do ecrã mostra o projeto ativo com nome, cores, forma e logo próprios. Faça duplo clique na Pill para abrir as Definições.\n\nTodas as definições, logos e perfis ficam guardados localmente no seu computador — sem necessidade de conta na nuvem no dia a dia.","help.topic.start.title":"HUD, pill e arranque","help.topic.start.nav":"Arranque","help.topic.start.body":"Há três formas de iniciar o Project HUD:\n\n1) Extensão do VS Code (AKC CCC VS)\nAbra o Context Control Center e clique em Activate. Por predefinição, a extensão também inicia o HUD automaticamente com o VS Code.\n\n2) Arranque automático com o Windows (Trial e Pro)\nMarque «Iniciar HUD com o Windows» nas Definições e clique em Aplicar.\n\n3) Iniciar / parar manualmente\nSe a Pill ainda não estiver em execução, pode copiar os comandos prontos para o terminal em Idioma e arranque.","help.topic.nav.title":"Navegação","help.topic.nav.nav":"Navegação","help.topic.nav.body":"No topo da janela do HUD existem cinco áreas:\n\nDefinições — cores, forma, modelo de caixa, ícone/padrão e logo próprio.\n\nArmazenamento — tamanho da base de conversas, cópia de prefs/perfis, experiências opcionais e compactação offline.\n\nAtivação — hash do dispositivo, ativação online e token R4IT….\n\nAjuda — guias curtos para cada função.\n\nAcerca — versão, edição e procura direta de atualizações.\n\nNo canto superior direito encontram-se a ajuda da página atual e o seletor de idioma.","help.topic.scope.title":"Âmbito e gravação","help.topic.scope.nav":"Âmbito","help.topic.scope.body":"Em Definições escolha o âmbito:\n\nProjeto (predefinição) grava só para o projeto Agents selecionado. Global é fallback sem prefs próprias.\n\nAplicar grava valores e atualiza a pill. Repor restaura o estado à abertura. Sem Aplicar, perde alterações ao fechar.","help.topic.look.title":"Look, predefinições e logo","help.topic.look.nav":"Look e logo","help.topic.look.body":"O modelo de caixa mostra as camadas da Pill e a mini pré-visualização apresenta logo o resultado. Clique em Aplicar para gravar as alterações na Pill real.\n\nCores e formas 3D combinam-se livremente (Pastel, Metal, Estúdio, Néon com Plano, Cubo, Relevo, Vidro ou Esfera).\n\nLogos e Orbs (Trial/Pro): escolha um Orb integrado ou selecione a sua própria imagem (PNG, JPG, BMP, GIF, ICO, WebP — máx. 2 MB e 2048×2048). Marque «Substituir logos próprios se existirem» para trocar um logo ativo por um Orb.","help.topic.storage.title":"Armazenamento e manutenção","help.topic.storage.nav":"Armazenamento","help.topic.storage.body":"O Cursor guarda o histórico de conversas localmente em state.vscdb. Quando esse ficheiro atinge vários gigabytes, mudar de projeto pode tornar-se lento.\n\nA página Armazenamento tem quatro separadores:\n• Armazenamento — ver o tamanho da base, definir um limite de aviso (2048 MB por predefinição) e escolher a pasta de cópia.\n• Cópia — exportar/importar definições (incluindo o logo) ou guardar perfis com nome.\n• Experimental — opções como o modo Silêncio durante deploys pesados (pausa leituras em segundo plano para manter a escrita fluida).\n• Alargado — fazer cópia de segurança ou compactar a base offline.\n\nImportante: feche o Cursor por completo (incluindo na área de notificação) antes de copiar ou compactar.","help.topic.activate.body":"Uma única ativação abrange tanto o Cursor como o VS Code neste computador.\n\nComo ativar Trial ou Pro:\n\n1. Compre o CCC Pro em ready-4-it.com/akc_ccc e instale o pacote licenciado.\n\n2. Em Ativação, clique em Abrir ativação online (o hash do dispositivo vai incluído).\n\n3. Introduza a chave de compra no site para receber o seu token de ativação (R4IT…).\n\n4. Cole o token R4IT… aqui e clique em Usar token de ativação.\n\nNota: AI Keep Clean (AKC) e AKC CCC são produtos independentes com chaves próprias.","help.topic.prefs.title":"Prefs e perfis","help.topic.prefs.body":"Em Armazenamento → Cópia (Pro) pode exportar e importar as suas definições em JSON ou guardar perfis com nome. O seu logo próprio é guardado automaticamente ao lado e reposto ao carregar.\n\nO número de perfis e logos disponíveis depende da edição (Free, Trial ou Pro).\n\nNa primeira visita a um projeto, o CCC atribui automaticamente um ícone estável que pode personalizar a qualquer momento.","help.topic.hudops.title":"Idioma, arranque automático e start/stop","help.topic.hudops.nav":"Idioma & início","help.topic.hudops.body":"Idioma do HUD\n\nUse o seletor no canto superior direito. «Interface do sistema» segue o idioma do Windows (inglês como recurso), ou escolha um idioma fixo. A janela reabre de imediato.\n\nArranque automático com o Windows (Trial e Pro)\n\nMarque «Iniciar HUD com o Windows» nas Definições e clique em Aplicar. Desmarque + Aplicar para desativar.\n\nIniciar / parar manualmente\n\nSe precisar, copie abaixo os comandos prontos para o seu terminal.","help.copy.section":"Copiar caminho / comandos","help.copy.hostNote":"Dica: no dia a dia, inicie o HUD via AKC CCC VS → Activate ou pelo arranque automático do Windows. Os comandos abaixo servem apenas como alternativa manual.","help.copy.btn":"Copiar","help.copy.copied":"Copiado","help.copy.folder":"Pasta do plugin","help.copy.startOne":"Start (uma linha)","help.copy.stopOne":"Stop (uma linha)","help.topic.privacy.title":"Privacidade","help.topic.privacy.nav":"Privacidade","help.topic.privacy.body":"O CCC lê localmente a seleção do Cursor para associar o chat ativo ao workspace. Assim a pill sabe qual projeto está em causa.\n\nPrefs HUD, posição, licença e assets ficam em %USERPROFILE%\\.cursor\\ (ccc-*.json e ccc-hud-assets). O CCC não precisa de cloud no dia a dia.\n\nEntrega licenciada (Trial / Pro)\n\n• Compra e checkout: ready-4-it.com (fluxo Payhip). Os termos vinculativos aparecem no checkout.\n• Ativação online: ready-4-it.com recebe o hash do dispositivo (derivado localmente do id da máquina, plataforma, hostname e um salt local em ccc-hud-device.json) mais a chave de licença de compra para emitir um token CCC assinado (R4IT…).\n• Atualizações in-app (Acerca → Verificar atualizações): o token R4IT, a versão Agents instalada e o id do módulo akc_ccc são enviados para o Streaming Zebra em api.streamingzebra.com — um serviço de entrega ready-4-it para transferências habilitadas (URLs de resgate de curta duração, não GitHub público).\n• O Zebra não recebe a sua palavra-passe Cursor nem o conteúdo do chat.\n\nAs atualizações Free usam apenas assets públicos de releases GitHub (sem token de licença; a transferência pode ser contada).\n\nLegal / privacidade: ready-4-it.com/privacy · support@ready-4-it.com · Produto: ready-4-it.com/akc_ccc · Entrega: streamingzebra.com\n\nO CCC é o irmão AKC da ready-4-it — não um produto da marca Cursor.\n\nFree / Public (freemium)\n\n• A contagem passa pelo Alveos Beacon (login.alveos.eu), não pela Streaming Zebra. São enviados id de instalação, evento (instalação, utilização, atualização, desinstalação), versão, tipo de cliente e plataforma. Sem chave de licença. O consentimento Zebra não cobre esta contagem.\n• Os ficheiros do plugin continuam a vir do GitHub e do Marketplace. O VSIX Free do VS Code é um acompanhante à parte e não entrega um pacote Agents.","help.sketch.nav":"DEFIN.  AJUDA  ATIV.  Sobre","help.sketch.content":"Conteúdo / área glass","activation.title":"Usar token de ativação","activation.sub":"Cole aqui o seu token de ativação CCC (R4IT…) — não a chave de compra da loja. Uma ativação é válida para o Cursor e o VS Code neste dispositivo.","activation.status":"Estado: {status} · {device}","activation.device.on":"Dispositivo ativado","activation.device.off":"Dispositivo não ativado","activation.hash":"Hash do dispositivo (ativação no site)","activation.copyUrl":"Copiar URL de ativação","activation.openOnline":"Abrir ativação online","activation.token":"Token de ativação (R4IT…)","activation.token.maskedHint":"Aceite — só é mostrada uma vista parcial. Clique no campo para colar um substituto.","activation.token.editHint":"Cole um token R4IT… completo e depois Usar token de ativação.","activation.use":"Usar token de ativação","activation.deactivate":"Desativar este dispositivo","activation.remove":"Remover","activation.tier":"Nível atual: {tier} — {hint}","activation.expiry.left":"Válido até {date} · restam {days} dias","activation.expiry.expired":"Expirado em {date}","activation.expiry.none":"Sem data de validade no token","activation.shop":"Abrir loja Pro / download","activation.how.full":"O CCC Pro está ativo neste dispositivo.\n• Atualize a qualquer momento em Acerca → Procurar atualizações.\n• Gerir licenças e transferências:","activation.how.trial":"Como ativar Trial ou Pro:\n1) Clique em Abrir ativação online e introduza a sua chave de compra.\n2) Copie o token de ativação gerado (R4IT…).\n3) Cole-o acima e clique em Usar token de ativação.","activation.how.free":"Como mudar para o CCC Pro:\n1) Obtenha o CCC Pro na ligação abaixo e instale o pacote licenciado.\n2) Clique em Abrir ativação online e introduza a sua chave de compra.\n3) Cole acima o token de ativação recebido (R4IT…).","about.update":"Um clique procura uma nova versão e instala-a diretamente.","about.update.check":"Verificar atualizações","about.update.legal":"Rede: Trial/Pro (ativado) enviam o token R4IT, a versão Agents instalada e o módulo akc_ccc à Streaming Zebra (api.streamingzebra.com) para habilitação e uma ligação de transferência efémera. Free não envia licença à Zebra. A contagem Free (instalação, utilização, atualização, desinstalação) vai ao Alveos Beacon (login.alveos.eu): id de instalação, evento, versão, tipo de cliente e plataforma. O VSIX Free do VS Code é um acompanhante à parte e não entrega pacotes Agents. Ver Ajuda → Privacidade.","about.update.consent.title":"Streaming Zebra — consentimento de rede","about.update.consent.body":"A entrega Trial/Pro licenciada contacta a Streaming Zebra (api.streamingzebra.com) com o token de licença R4IT, a versão Agents instalada e o módulo akc_ccc. Este consentimento cobre a Zebra: instalação, verificação de atualização, transferência e desinstalação. As transferências usam URL efémeras.\n\nFree/Public não é contado pela Zebra. Essa contagem vai ao Alveos Beacon (login.alveos.eu) e não precisa deste consentimento.\n\nTermos: streamingzebra.com/terms\nPrivacidade: ready-4-it.com/privacy · streamingzebra.com/privacy","about.update.consent.checkbox":"Concordo com este uso de rede para a Streaming Zebra (Trial/Pro: instalação, atualização, transferência, desinstalação).","about.update.consent.ok":"Aceitar e continuar","about.update.consent.cancel":"Cancelar","about.update.consent.required":"Autorize uma vez a procura de atualizações (Acerca → Procurar atualizações).","about.update.freePingOk":"As atualizações da edição gratuita são entregues pelo Marketplace ou GitHub.","about.update.installConfirm":"A versão {version} está disponível. Transferir e instalar agora?","about.update.installConfirmFree":"A atualização gratuita {version} está disponível. Transferir e instalar agora?","about.update.installOk":"Versão {version} instalada com sucesso.","about.update.installFail":"Falha ao instalar a atualização: {error}","about.update.restartAsk":"Reiniciar o Project HUD para carregar a nova versão?","about.update.upToDate":"Sem versão mais recente. Atual: {version}","about.update.missingCli":"Ferramenta de atualização não encontrada. Reinstale o plugin.","about.update.missingApply":"Instalador de atualizações não encontrado. Reinstale o plugin.","about.update.noReply":"Sem resposta do verificador de atualizações.","about.update.checkFail":"Falha ao procurar atualizações","about.update.devHint":"Nota: a verificação usou DEV (CCC_ZEBRA_DEV ou %USERPROFILE%\\.ccc\\zebra-dev). Para licenças Life remova o marcador / retire a variável de ambiente e tente novamente.","about.update.zebraTokenUnknown":"O token de ativação não foi reconhecido ou expirou. Reative em Ativação ou verifique As minhas licenças em ready-4-it.com.","about.update.zebraWrongField":"Transfira uma vez o pacote atual em As minhas licenças em ready-4-it.com — a sua ativação continua válida.","about.update.zebraWrongCredential":"Transfira uma vez o pacote atual em As minhas licenças em ready-4-it.com — a sua ativação continua válida.","about.update.zebraDevToken":"Token de ativação DEV: o Pro é válido localmente, mas o Streaming Zebra ainda não tem registo de entrega para este token (falta o hash do token no CRM?). Registe o token no Zebra DEV ou use uma licença Life da loja.","about.update.releaseUnavailable":"O serviço de atualizações está temporariamente indisponível. Tente mais tarde ou transfira em As minhas licenças em ready-4-it.com.","about.pro.body":"Desbloqueie logos próprios, padrões, perfis e cópia de segurança com o CCC Pro:","about.pro.shop":"Abrir loja Pro","about.legal.title":"Aviso legal","about.legal.terms":"Termos de utilização","about.legal.privacy":"Privacidade","about.legal.trademark":"Cursor, VS Code e Copilot são marcas registadas dos respetivos proprietários; este produto não é afiliado nem recomendado por eles.","about.update.checking":"A verificar…","hud.menu.settings":"Definições","pill.home":"Home é o scratchbook do Cursor: uma conversa sem projeto.","settings.lookPreset.back":"Voltar · Borda","settings.iconLogo":"Ícone/Logo","settings.iconLogo.back":"Voltar · Borda","settings.inspector.iconLogo":"Inspetor — substituir ícone/logo","settings.logo.recent":"Recentes:","settings.logo.recent.pick":"O mais recente","settings.logo.overwrite":"Substituir logos próprios se existirem","settings.logo.overwrite.blocked":"Está ativo um logo próprio. Marque «Substituir logos próprios se existirem» para o trocar por um preset de orb.","about.update.networkFail":"Não foi possível contactar o serviço de atualizações ({host}): {detail}. Tente mais tarde ou transfira em As minhas licenças em ready-4-it.com.","about.update.zebraCrmHashMissing":"A sua licença é válida localmente; a entrega online ainda está a sincronizar. Tente dentro de momentos ou transfira em As minhas licenças em ready-4-it.com."};export const es={"lang.label":"Idioma","lang.auto":"GUI del sistema","nav.settings":"Ajustes","nav.storage":"Almacenamiento","nav.help":"Ayuda","nav.activation":"Activación","nav.about":"Acerca de","hud.copy.scope":"Copiar ámbito, versión, versión VS, derivado y proyecto","hud.copy.scope.done":"Copiado","hud.copy.field.scope":"Ámbito","hud.copy.field.project":"Proyecto","hud.copy.field.version":"Versión","hud.copy.field.derivative":"Derivado","hud.copy.field.variation":"Variante de VS Code","hud.copy.field.vsVersion":"Versión de VS Code","hud.copy.field.menu":"Menú","hud.copy.field.content":"Contenido","hud.copy.edit.project":"proyecto","settings.scope":"Ámbito:","settings.scope.project":"Proyecto (predeterminado)","settings.scope.hint.project":"Edición: proyecto Agents actual (ámbito Proyecto)","settings.scope.hint.global":"Edición: Global (reserva sin anulación de proyecto)","pill.scope":"Ámbito:","settings.size":"Tamaño:","settings.style":"Estilo:","settings.style.stripes":"Rayas","settings.lookPreset":"Preajuste look","settings.reset":"Restablecer","settings.apply":"Aplicar","settings.close":"Cerrar","settings.boxModel":"Modelo de caja (clic = capa)","settings.inspector.border":"Inspector — Borde","settings.inspector.border.purpose":"El anillo de color del modelo de caja es el marco de la pill. Color y grosor se aplican tras Aplicar.","settings.inspector.margin.purpose":"El margen exterior es el espacio fuera del marco.","settings.inspector.padding.purpose":"El margen interior es el espacio dentro del marco, alrededor de la etiqueta.","settings.inspector.content.purpose":"El contenido es la etiqueta: fuente, relleno y color del texto.","settings.inspector.margin":"Inspector — Margen exterior","settings.inspector.padding":"Inspector — Margen interior","settings.inspector.content":"Inspector — Contenido","settings.inspector.preset":"Inspector — Color y forma","settings.borderColor":"Color del borde","settings.borderWidth":"Ancho del borde","settings.margin":"Margen exterior (Margin)","settings.padding":"Margen interior (Padding)","settings.font":"Fuente","settings.fontSize":"Tamaño de fuente","settings.fill":"Color de relleno","settings.textColor":"Color del texto","settings.iconTitle":"Icono / Patrón","settings.mode":"Modo:","settings.iconColor":"Color del icono:","settings.pattern":"Patrón:","settings.logo":"Logo personalizado:","settings.logo.browse":"Examinar…","settings.logo.hint.empty":"Sin logo personalizado — opcional vía Examinar…","settings.logo.hint.custom":"Logo personalizado activo","settings.logo.hint.repo":"El logo permanece en el repo del proyecto — los cambios del archivo se ven en la pill.","settings.logo.hint.orb":"Orbe de preajuste activo (sin ruta de archivo)","settings.prefs.export":"Exportar prefs","settings.prefs.import":"Importar prefs","settings.profile.save":"Guardar perfil","settings.profile.load":"Cargar perfil","settings.prefs.vsProfile":"Exportar e Importar mueven un archivo. Guardar y Cargar perfil guardan una copia con nombre en la carpeta de perfiles y cuentan para el límite. Apply lo pone en la pill.","settings.prefs.loaded":"Cargado {name}. Está en este diálogo (ámbito: {scope}). Apply lo pone en la pill.","settings.autostart":"Iniciar el HUD con Windows","settings.zebra.consent":"Permitir acceso a la red para buscar actualizaciones (desactivable en cualquier momento).","settings.pro.line":"Trial/Pro: Patrón / Logo / Prefs — Logos {logos}/{logoMax} · Perfiles {profiles}/{profMax} — ready-4-it.com/akc_ccc","settings.theme.hint":"Color y forma van por separado. Pastel, Metal, Studio y Neón valen cada uno con Ninguna, cubo, texto, cristal o esfera. Icono/logo sin cambios. La pill se actualiza tras Aplicar.","settings.theme.bgTitle":"Fondo (orbe → logo)","settings.theme.bgHint":"Reemplaza icono/logo — acción separada de colores look.","storage.title":"Almacenamiento / Memoria","storage.sub":"Base de datos local de chats de Cursor (state.vscdb). Solo se consulta el tamaño — nunca se modifica con Cursor abierto. Copia y compactación exigen cerrar Cursor por completo.","storage.dbPath":"Ruta de la base de datos","storage.sizeLabel":"Tamaño: {size}","storage.sizeMissing":"Archivo de base de datos no encontrado","storage.warnMb":"Umbral de aviso (MB)","storage.warnOver":"Por encima del umbral de aviso ({mb} MB) — considera compactar sin conexión tras cerrar Cursor.","storage.warnOk":"Por debajo del umbral de aviso ({mb} MB).","storage.softCap":"Límite flexible de sesión (para la futura memoria MCP)","storage.archiveDir":"Carpeta de archivo / copia (vacío = ~/.cursor-archive)","storage.browse":"Examinar…","storage.mcpEnable":"Activar memoria MCP (preferencia)","storage.mcpHint":"Trial/Pro: activa la memoria MCP local (archive_session_chunk). Free/Public: solo tamaño del almacenamiento y archivos recientes.","storage.mcp.proOnly":"La memoria MCP requiere Trial/Pro (activado). Abre ready-4-it.com/akc_ccc para mejorar.","storage.refresh":"Actualizar tamaño","storage.backup":"Copia de seguridad ahora","storage.compact":"Compactar sin conexión…","storage.compact.confirm":"Esto limpia entradas grandes de caché y reduce la base de datos. Cursor debe permanecer completamente cerrado. ¿Continuar?","storage.apply":"Guardar prefs","storage.openHelp":"Abrir tema de ayuda","storage.saved":"Prefs de almacenamiento guardadas.","storage.status.cursorRunning":"Cursor se está ejecutando — ciérralo por completo antes de la copia de seguridad o la compactación sin conexión.","storage.status.cursorQuit":"Cursor no detectado — se puede hacer copia / compactación sin conexión.","storage.busy.backup":"Haciendo copia de seguridad…","storage.busy.compact":"Compactando sin conexión (puede tardar minutos en bases grandes)…","storage.ok.backup":"Copia de seguridad terminada.","storage.ok.compact":"Compactación sin conexión terminada. Reinicia Cursor cuando quieras.","storage.err.helpers":"Faltan archivos auxiliares de almacenamiento. Reinstala el plugin.","storage.err.cursorRunning":"Cierra primero Cursor por completo (todos sus procesos) y vuelve a intentarlo.","storage.err.exit":"El script de mantenimiento terminó con el código {code}. Consulta la ventana de PowerShell para ver los detalles.","storage.archives.title":"Archivos CCC (solo lectura)","storage.archives.sub":"Búsqueda en CCC agent_memory.db — no el Unarchive de la barra Cursor/VS Code. Active primero MCP Memory y archive fragmentos. Restaurar sigue siendo función del host.","storage.archives.recent":"Recientes","storage.archives.search":"Buscar","storage.archives.searchPro":"La búsqueda de archivos es Trial/Pro. Se abre ready-4-it.com/akc_ccc — Free solo guarda una lista Recientes corta.","storage.archives.empty":"Aún no hay archivos CCC. Active MCP Memory, luego archive_session_chunk / resúmenes.","storage.archives.missing":"Falta el visor de archivos. Reinstala el plugin.","storage.archives.note":"{count} entrada(s) · {path}","storage.archives.hint":"Índice CCC de solo lectura. Unarchive del host: barra Agents → filtro Archivado → Unarchive.","storage.quiet.title":"Silencio / suspensión (despliegue y E/S intensiva)","storage.quiet.sub":"Con Silencio activo, el HUD pausa las consultas de identidad a las bases de Cursor/VS Code para que escribir en Agents siga siendo fluido durante despliegues o sincronizaciones pesadas. La pill muestra el silencio con un temporizador.","storage.quiet.enabled":"Activar reglas de Silencio","storage.quiet.auto":"Suspensión automática cuando las lecturas del HUD siguen lentas (opcional — puede añadir carga)","storage.quiet.defaultSleep":"Suspensión predeterminada (segundos)","storage.quiet.rules":"Reglas (una por línea: nombre=segundos)","storage.quiet.hint":"Ejemplos: deploy.exe=300  o  deploy.ps1=300  o  WinSCP.exe=180\nSe compara el nombre del proceso (deploy.exe) o una subcadena de la línea de comandos solo entre powershell/pwsh/cmd (deploy.ps1). No el título de ventana. Deja la suspensión automática desactivada salvo necesidad. Prefs: %USERPROFILE%\\.cursor\\ccc-hud-quiet-prefs.json","storage.exp.title":"Experimentos (opcional)","storage.exp.sub":"Desactivado por defecto = pill estable como antes. Las funciones nuevas (watch, silencio, UIA, base glass) solo cuando quieras probarlas — pueden entrecortar el escritorio.","storage.exp.enabled":"Desbloquear experimentos","storage.exp.hudWatch":"HUD watch (seguir la identidad)","storage.exp.quiet":"Reglas de Silencio / suspensión","storage.exp.uia":"Análisis UIA de la barra lateral (VS Code)","storage.exp.glass":"Lecturas de Glass / state.vscdb","storage.exp.hint":"Tras los cambios: reinicia el HUD (Stop → Start). Prefs: %USERPROFILE%\\.cursor\\ccc-hud-experiments.json","storage.tab.main":"Almacenamiento","storage.tab.bak":"Copia","storage.tab.ext":"Ampliado","storage.bak.title":"Prefs, perfiles y logo","storage.bak.sub":"Exportar e Importar mueven un JSON a cualquier sitio. Guardar y Cargar perfil conservan una instantánea con nombre en la carpeta de perfiles y cuentan para el límite. El archivo del logo se escribe junto a ese JSON y se restaura con él. Aplicar sigue escribiendo el aspecto en la pill.","storage.help.bak.goal.title":"Qué se guarda","storage.help.bak.goal.body":"El JSON guarda colores, forma y la ruta del logo. La imagen en sí es el archivo .logo junto al JSON. Los orbs (Pastell, Metall, 3D, Neon) se restauran desde ese archivo, o desde el arte integrado si falta la copia.","storage.ext.title":"Ampliado (MCP y mantenimiento)","storage.ext.sub":"Preferencia de memoria MCP (Trial/Pro), copia de seguridad y compactación sin conexión de Cursor state.vscdb — solo con Cursor totalmente cerrado.","storage.help.close":"Cerrar","storage.help.toggle":"Ayuda","storage.help.empty":"Aún no hay texto de ayuda para esta pestaña.","storage.ext.recommend":"Consejo: cierra Cursor por completo antes de la copia de seguridad o la compactación sin conexión. Mira la línea de estado bajo los botones.","storage.help.main":"state.vscdb contiene los datos de chat de Agents. Aquí: leer el tamaño, fijar el umbral de aviso y el límite flexible, elegir la carpeta de archivo, explorar archivos de sesión.\n\nPrefs: %USERPROFILE%\\.cursor\\ccc-memory-prefs.json\n\nCopia y compactación están en Ampliado — cierra Cursor primero.","storage.help.exp":"Los experimentos están desactivados por defecto (pill estable).\n\nDesbloquea el interruptor general y activa: HUD watch, Silencio, UIA, base glass.\nLas reglas de Silencio (deploy.exe=300) pausan las consultas de identidad.\n\nPrefs: ccc-hud-experiments.json y ccc-hud-quiet-prefs.json en %USERPROFILE%\\.cursor\\\nTras guardar: HUD Stop → Start.","storage.help.ext":"Memoria MCP (Trial/Pro): preferencia para la memoria local de sesión.\n\nCopia de seguridad: copia state.vscdb en la carpeta de archivo — solo con Cursor cerrado.\n\nCompactación sin conexión: reduce la base tras cerrar Cursor.\n\nNunca compactes con Cursor abierto.","storage.help.main.goal.title":"Qué hace esta pestaña","storage.help.main.goal.body":"Leer el tamaño de state.vscdb, fijar el umbral de aviso y el límite flexible, elegir la carpeta de archivo y explorar los archivos de sesión de CCC. Nunca compactes con Cursor abierto.","storage.help.main.defaults.title":"Valores predeterminados","storage.help.main.defaults.body":"Umbral de aviso: 2048 MB\nLímite flexible: 40 (futura memoria MCP)\nCarpeta de archivo: ~/.cursor-archive si está vacío\nMemoria MCP: desactivada (preferencia Trial/Pro)\nPrefs: %USERPROFILE%\\.cursor\\ccc-memory-prefs.json","storage.help.main.do.title":"Uso diario","storage.help.main.do.body":"Actualiza el tamaño de vez en cuando.\nGuarda las prefs tras los cambios.\nUsa los archivos recientes (Free: lista corta; Pro: búsqueda).\nCopia y compactación están en Ampliado — cierra Cursor primero.","storage.help.main.critical.title":"Cuando algo parece atascado","storage.help.main.critical.body":"Base muy por encima del aviso + Agents se cuelga → pestaña Ampliado.\nEl escritorio se entrecorta por el HUD → pestaña Experimental, desactiva Silencio/UIA, HUD Stop → Start.","storage.help.main.steps.title":"Compactación sin conexión (Ampliado)","storage.help.main.steps.body":"1) Cierra Cursor (bandeja, hasta que no quede Cursor.exe)\n2) Ampliado → Compactar sin conexión\n3) Reinicia Cursor al terminar","storage.help.exp.goal.title":"Qué son los experimentos","storage.help.exp.goal.body":"Watch + Glass mantienen la pill en el proyecto de Agents correcto (activado por defecto).\nSilencio y UIA son los interruptores arriesgados — actívalos solo a propósito.","storage.help.exp.defaults.title":"Valores predeterminados","storage.help.exp.defaults.body":"Interruptor general de experimentos: desactivado\nWatch + Glass: activados (identidad)\nSilencio + UIA: desactivados\nArchivos: ccc-hud-experiments.json, ccc-hud-quiet-prefs.json","storage.help.exp.do.title":"Cuándo tocarlo","storage.help.exp.do.body":"Uso diario: deja el interruptor general desactivado — Watch/Glass siguen funcionando.\nSilencio solo con reglas concretas (p. ej. deploy.exe=300).\nUIA solo brevemente — a menudo congela el escritorio.","storage.help.exp.critical.title":"Si el IDE se entrecorta","storage.help.exp.critical.body":"El IDE se entrecorta con el HUD → desactiva Silencio/UIA, guarda las prefs, HUD Stop → Start.\nDeja desactivada la suspensión automática de Silencio — ella misma añade carga.","storage.help.exp.steps.title":"Tras los cambios","storage.help.exp.steps.body":"Guarda las prefs en la pestaña.\nHUD Stop → Start.","storage.help.ext.goal.title":"Ampliado / mantenimiento","storage.help.ext.goal.body":"Preferencia de memoria MCP (Trial/Pro), copia de seguridad y compactación sin conexión de state.vscdb — solo con Cursor totalmente cerrado.","storage.help.ext.defaults.title":"Reglas de seguridad","storage.help.ext.defaults.body":"La copia de seguridad guarda state.vscdb en tu carpeta de archivo.\nLa compactación sin conexión reduce la base de chats.\nCCC rechaza ambas mientras siga activo algún proceso de Cursor.","storage.help.ext.do.title":"Flujo recomendado","storage.help.ext.do.body":"Revisa la línea de estado (en ejecución o cerrado).\nHaz primero la copia cuando la base sea enorme.\nCompacta solo tras cerrar; puede tardar minutos.\nReinicia Cursor tras compactar.","storage.help.ext.critical.title":"Nunca hagas esto","storage.help.ext.critical.body":"Nunca compactes con Cursor abierto — podrías dañar la base de datos de chats.","storage.help.ext.steps.title":"Pasos de la compactación","storage.help.ext.steps.body":"1) Cierra Cursor por completo\n2) Ampliado → Compactar sin conexión → confirmar\n3) Espera el estado OK\n4) Inicia Cursor de nuevo","help.nav":"Temas","help.drawer.toggle":"Ayuda","help.drawer.tip":"Ayuda de esta página","help.drawer.close":"Cerrar","help.drawer.openTopic":"Abrir en Ayuda","help.drawer.look.title":"Aspecto","help.drawer.look.body":"El modelo de caja es el esquema de capas. La minivista previa es la pill. Aquí se eligen color y forma, y Aplicar los escribe en la pill. Icono y logo son el otro control de Ajustes.","help.drawer.logo.title":"Icono y logo","help.drawer.logo.body":"Pastell, Metall, 3D y Neon sustituyen el icono. Un logo propio se mantiene mientras no se marque sobrescribir. La exportación y los perfiles en Almacenamiento → Copia guardan el archivo del logo junto al JSON.","help.drawer.storage.title":"Almacenamiento de Cursor","help.drawer.storage.body":"state.vscdb contiene los datos de chat de Agents. Esta pestaña lee el tamaño, el umbral de aviso y la carpeta de archivo. Copiar o compactar esa base está en Ampliado, y solo después de cerrar Cursor.","help.drawer.backup.title":"Prefs y perfiles","help.drawer.backup.body":"Exportar mueve un archivo JSON adonde elijas. Guardar perfil conserva una copia con nombre en la carpeta de perfiles y cuenta para el límite. El archivo del logo se escribe junto al JSON y vuelve al importar o cargar.","help.drawer.experiments.title":"Experimentos","help.drawer.experiments.body":"Watch y Glass mantienen la pill en el chat de Agents seleccionado. Silencio y UIA siguen desactivados salvo que los actives. Tras un cambio, detén el HUD y vuelve a iniciarlo.","help.drawer.hygiene.title":"Copia de seguridad de la base","help.drawer.hygiene.body":"Copia de seguridad ahora copia state.vscdb. Compactar sin conexión reduce la base. Ambas solo se ejecutan con Cursor completamente cerrado.","help.drawer.activate.title":"De Free a Pro","help.drawer.activate.body":"Consigue CCC Pro en ready-4-it.com/akc_ccc, instala el paquete con licencia y activa aquí con el hash del dispositivo y tu token R4IT….","help.drawer.about.title":"Actualizaciones","help.drawer.about.body":"Pulsa Buscar actualizaciones para descargar e instalar directamente una versión nueva. La primera vez, el HUD te pedirá permiso una sola vez.","help.topic.overview.title":"Resumen","help.topic.overview.nav":"Resumen","help.topic.overview.body":"AI Keep Clean Context Control Center (CCC) da a cada proyecto en Cursor y VS Code una identidad visual clara al instante.\n\nLa Pill flotante en el borde de la pantalla muestra el proyecto activo con su nombre, colores, forma y logo. Haz doble clic en la Pill para abrir Ajustes.\n\nTodos los ajustes, logos y perfiles se guardan localmente en tu equipo — sin cuenta en la nube para el uso diario.","help.topic.start.title":"HUD, pill e inicio","help.topic.start.nav":"Inicio","help.topic.start.body":"Hay tres formas de iniciar el Project HUD:\n\n1) Extensión de VS Code (AKC CCC VS)\nAbre Context Control Center y pulsa Activate. Por defecto, la extensión también inicia el HUD automáticamente con VS Code.\n\n2) Inicio automático con Windows (Trial y Pro)\nMarca «Iniciar HUD con Windows» en Ajustes y pulsa Aplicar.\n\n3) Inicio / parada manual\nSi la Pill aún no está en marcha, puedes copiar los comandos listos para terminal en Idioma e inicio.","help.topic.nav.title":"Navegación","help.topic.nav.nav":"Navegación","help.topic.nav.body":"En la parte superior de la ventana del HUD hay cinco secciones:\n\nAjustes — colores, forma, modelo de caja, icono/patrón y logo propio.\n\nAlmacenamiento — tamaño de la base de chats, copia de prefs/perfiles, experimentos opcionales y compactación sin conexión.\n\nActivación — hash del dispositivo, activación en línea y token R4IT….\n\nAyuda — guías breves de cada función.\n\nAcerca de — versión, edición y búsqueda directa de actualizaciones.\n\nArriba a la derecha están la ayuda de la página actual y el selector de idioma.","help.topic.scope.title":"Ámbito y guardado","help.topic.scope.nav":"Ámbito","help.topic.scope.body":"En Ajustes elija el ámbito:\n\nProyecto (predeterminado) guarda solo para el proyecto Agents seleccionado. Global es reserva sin prefs propias.\n\nAplicar escribe valores y actualiza la pill. Restablecer restaura el estado al abrir. Sin Aplicar, se pierden cambios al cerrar.","help.topic.look.title":"Look, preajustes y logo","help.topic.look.nav":"Look y logo","help.topic.look.body":"El modelo de caja muestra las capas de la Pill y la minivista previa enseña el resultado al instante. Pulsa Aplicar para escribir los cambios en la Pill real.\n\nColores y formas 3D se combinan libremente (Pastel, Metal, Estudio, Neón con Plano, Cubo, Relieve, Cristal o Esfera).\n\nLogos y Orbs (Trial/Pro): elige un Orb integrado o selecciona tu propia imagen (PNG, JPG, BMP, GIF, ICO, WebP — máx. 2 MB y 2048×2048). Marca «Sobrescribir logos propios si existen» para sustituir un logo propio por un Orb.","help.topic.storage.title":"Almacenamiento y mantenimiento","help.topic.storage.nav":"Almacenamiento","help.topic.storage.body":"Cursor guarda el historial de chats localmente en state.vscdb. Cuando ese archivo crece varios gigabytes, cambiar de proyecto puede volverse lento.\n\nLa página Almacenamiento tiene cuatro pestañas:\n• Almacenamiento — ver el tamaño de la base, fijar un umbral de aviso (2048 MB por defecto) y elegir la carpeta de copia.\n• Copia — exportar/importar tus ajustes (incluido el logo) o guardar perfiles con nombre.\n• Experimental — opciones como el modo Silencio durante despliegues pesados (pausa lecturas en segundo plano para escribir con fluidez).\n• Ampliado — hacer copia de seguridad o compactar la base sin conexión.\n\nImportante: cierra Cursor por completo (también en la bandeja del sistema) antes de copiar o compactar.","help.topic.activate.body":"Una sola activación cubre tanto Cursor como VS Code en este ordenador.\n\nCómo activar Trial o Pro:\n\n1. Compra CCC Pro en ready-4-it.com/akc_ccc e instala el paquete con licencia.\n\n2. En Activación, pulsa Abrir activación en línea (se incluye el hash del dispositivo).\n\n3. Introduce tu clave de compra en la web para recibir tu token de activación (R4IT…).\n\n4. Pega el token R4IT… aquí y pulsa Usar token de activación.\n\nNota: AI Keep Clean (AKC) y AKC CCC son productos independientes con claves distintas.","help.topic.prefs.title":"Prefs y perfiles","help.topic.prefs.body":"En Almacenamiento → Copia (Pro) puedes exportar e importar tus ajustes en JSON o guardar perfiles con nombre. Tu logo propio se guarda automáticamente junto al archivo y se restaura al cargar.\n\nEl número de perfiles y logos disponibles depende de tu edición (Free, Trial o Pro).\n\nAl abrir un proyecto por primera vez, CCC asigna un icono estable automáticamente; puedes cambiarlo cuando quieras en Ajustes.","help.topic.hudops.title":"Idioma, inicio automático y start/stop","help.topic.hudops.nav":"Idioma e inicio","help.topic.hudops.body":"Idioma del HUD\n\nUsa el selector arriba a la derecha. «Interfaz del sistema» sigue el idioma de Windows (inglés como reserva), o elige un idioma fijo. La ventana se reabre al instante.\n\nInicio automático con Windows (Trial y Pro)\n\nMarca «Iniciar HUD con Windows» en Ajustes y pulsa Aplicar. Desmarca + Aplicar para desactivarlo.\n\nInicio / parada manual\n\nSi lo necesitas, copia abajo los comandos listos para tu terminal.","help.copy.section":"Copiar ruta / comandos","help.copy.hostNote":"Consejo: habitualmente inicias el HUD desde AKC CCC VS → Activate o con el inicio automático de Windows. Los comandos de abajo son solo una alternativa manual.","help.copy.btn":"Copiar","help.copy.copied":"Copiado","help.copy.folder":"Carpeta del plugin","help.copy.startOne":"Start (una línea)","help.copy.stopOne":"Stop (una línea)","help.topic.privacy.title":"Privacidad","help.topic.privacy.nav":"Privacidad","help.topic.privacy.body":"CCC lee localmente la selección de Cursor para asociar el chat activo al workspace. Así la pill sabe qué proyecto corresponde.\n\nPrefs HUD, posición, licencia y assets quedan en %USERPROFILE%\\.cursor\\ (ccc-*.json y ccc-hud-assets). CCC no necesita nube en el día a día.\n\nEntrega con licencia (Trial / Pro)\n\n• Compra y checkout: ready-4-it.com (flujo Payhip). Las condiciones vinculantes se muestran en el checkout.\n• Activación en línea: ready-4-it.com recibe el hash del dispositivo (derivado localmente del id de máquina, plataforma, hostname y una sal local en ccc-hud-device.json) más su clave de licencia de compra para emitir un token CCC firmado (R4IT…).\n• Actualizaciones in-app (Acerca de → Buscar actualizaciones): su token R4IT, la versión Agents instalada y el id de módulo akc_ccc se envían a Streaming Zebra en api.streamingzebra.com — un servicio de entrega de ready-4-it para descargas habilitadas (URL de canje de corta duración, no GitHub público).\n• Zebra no recibe su contraseña de Cursor ni el contenido del chat.\n\nLas actualizaciones Free usan solo recursos públicos de GitHub (sin token de licencia; la descarga puede contarse).\n\nLegal / privacidad: ready-4-it.com/privacy · support@ready-4-it.com · Producto: ready-4-it.com/akc_ccc · Entrega: streamingzebra.com\n\nCCC es la hermana AKC de ready-4-it — no un producto de marca Cursor.\n\nFree / Public (freemium)\n\n• El conteo va por Alveos Beacon (login.alveos.eu), no por Streaming Zebra. Se envían id de instalación, evento (instalación, uso, actualización, desinstalación), versión, tipo de cliente y plataforma. Sin clave de licencia. El consentimiento Zebra no cubre este conteo.\n• Los archivos del plugin siguen viniendo de GitHub y del Marketplace. El VSIX Free de VS Code es un acompañante aparte y no entrega un paquete Agents.","help.sketch.nav":"AJUSTES  AYUDA  ACTIV.  Acerca de","help.sketch.content":"Contenido / área glass","activation.title":"Usar token de activación","activation.sub":"Pega aquí tu token de activación de CCC (R4IT…) — no la clave de compra de la tienda. Una activación sirve para Cursor y VS Code en este dispositivo.","activation.status":"Estado: {status} · {device}","activation.device.on":"Dispositivo activado","activation.device.off":"Dispositivo no activado","activation.hash":"Hash del dispositivo (activación web)","activation.copyUrl":"Copiar URL de activación","activation.openOnline":"Abrir activación online","activation.token":"Token de activación (R4IT…)","activation.token.maskedHint":"Aceptado — solo se muestra una vista parcial. Haga clic en el campo para pegar un sustituto.","activation.token.editHint":"Pegue un token R4IT… completo y luego Usar token de activación.","activation.use":"Usar token de activación","activation.deactivate":"Desactivar este dispositivo","activation.remove":"Eliminar","activation.tier":"Nivel actual: {tier} — {hint}","activation.expiry.left":"Válido hasta {date} · quedan {days} días","activation.expiry.expired":"Caducó el {date}","activation.expiry.none":"Sin fecha de caducidad en el token","activation.shop":"Abrir tienda Pro / descarga","activation.how.full":"CCC Pro está activo en este dispositivo.\n• Actualiza en cualquier momento desde Acerca de → Buscar actualizaciones.\n• Gestionar licencias y descargas:","activation.how.trial":"Cómo activar Trial o Pro:\n1) Pulsa Abrir activación en línea e introduce tu clave de compra.\n2) Copia el token de activación generado (R4IT…).\n3) Pégalo arriba y pulsa Usar token de activación.","activation.how.free":"Cómo pasar a CCC Pro:\n1) Consigue CCC Pro en el enlace de abajo e instala el paquete con licencia.\n2) Pulsa Abrir activación en línea e introduce tu clave de compra.\n3) Pega arriba el token de activación recibido (R4IT…).","about.update":"Un clic comprueba si hay una versión nueva y la instala directamente.","about.update.check":"Buscar actualizaciones","about.update.legal":"Red: Trial/Pro (activado) envían el token R4IT, la versión Agents instalada y el módulo akc_ccc a Streaming Zebra (api.streamingzebra.com) para la autorización y un enlace de descarga efímero. Free no envía licencia a Zebra. El conteo Free (instalación, uso, actualización, desinstalación) va a Alveos Beacon (login.alveos.eu): id de instalación, evento, versión, tipo de cliente y plataforma. El VSIX Free de VS Code es un acompañante aparte y no entrega paquetes Agents. Véase Ayuda → Privacidad.","about.update.consent.title":"Streaming Zebra — consentimiento de red","about.update.consent.body":"La entrega Trial/Pro con licencia contacta Streaming Zebra (api.streamingzebra.com) con su token de licencia R4IT, la versión Agents instalada y el módulo akc_ccc. Este consentimiento cubre Zebra: instalación, comprobación de actualización, descarga y desinstalación. Las descargas usan URL efímeras.\n\nFree/Public no se cuenta a través de Zebra. Ese conteo va a Alveos Beacon (login.alveos.eu) y no necesita este consentimiento.\n\nCondiciones: streamingzebra.com/terms\nPrivacidad: ready-4-it.com/privacy · streamingzebra.com/privacy","about.update.consent.checkbox":"Acepto este uso de red para Streaming Zebra (Trial/Pro: instalación, actualización, descarga, desinstalación).","about.update.consent.ok":"Aceptar y continuar","about.update.consent.cancel":"Cancelar","about.update.consent.required":"Autoriza una vez la búsqueda de actualizaciones (Acerca de → Buscar actualizaciones).","about.update.freePingOk":"Las actualizaciones de la edición gratuita llegan a través del Marketplace o GitHub.","about.update.installConfirm":"La versión {version} está disponible. ¿Descargar e instalar ahora?","about.update.installConfirmFree":"La actualización gratuita {version} está disponible. ¿Descargar e instalar ahora?","about.update.installOk":"Versión {version} instalada correctamente.","about.update.installFail":"Error al instalar la actualización: {error}","about.update.restartAsk":"¿Reiniciar el Project HUD para cargar la nueva versión?","about.update.upToDate":"No hay una versión más reciente. Actual: {version}","about.update.missingCli":"No se encontró la herramienta de actualización. Reinstala el plugin.","about.update.missingApply":"No se encontró el instalador de actualizaciones. Reinstala el plugin.","about.update.noReply":"El comprobador de actualizaciones no respondió.","about.update.checkFail":"Error al buscar actualizaciones","about.update.devHint":"Nota: la comprobación usó DEV (CCC_ZEBRA_DEV o %USERPROFILE%\\.ccc\\zebra-dev). Para licencias Life elimina el marcador / quita la variable de entorno y vuelve a intentarlo.","about.update.zebraTokenUnknown":"El token de activación no se reconoce o ha caducado. Reactiva en Activación o revisa Mis licencias en ready-4-it.com.","about.update.zebraWrongField":"Descarga una vez el paquete actual desde Mis licencias en ready-4-it.com — tu activación sigue siendo válida.","about.update.zebraWrongCredential":"Descarga una vez el paquete actual desde Mis licencias en ready-4-it.com — tu activación sigue siendo válida.","about.update.zebraDevToken":"Token de activación DEV: Pro es válido localmente, pero Streaming Zebra aún no tiene registro de entrega para este token (¿falta el hash del token en CRM?). Registra el token en Zebra DEV o usa una licencia Life de la tienda.","about.update.releaseUnavailable":"El servicio de actualizaciones no está disponible temporalmente. Inténtalo más tarde o descarga desde Mis licencias en ready-4-it.com.","about.pro.body":"Desbloquea logos propios, patrones, perfiles y copia de seguridad con CCC Pro:","about.pro.shop":"Abrir tienda Pro","about.legal.title":"Aviso legal","about.legal.terms":"Condiciones de uso","about.legal.privacy":"Privacidad","about.legal.trademark":"Cursor, VS Code y Copilot son marcas registradas de sus respectivos propietarios; este producto no está afiliado ni respaldado por ellos.","about.update.checking":"Comprobando…","hud.menu.settings":"Ajustes","pill.home":"Home es el scratchbook de Cursor: un chat sin proyecto.","settings.lookPreset.back":"Volver · Borde","settings.iconLogo":"Icono/Logo","settings.iconLogo.back":"Volver · Borde","settings.inspector.iconLogo":"Inspector — sustituir icono/logo","settings.logo.recent":"Recientes:","settings.logo.recent.pick":"El más reciente","settings.logo.overwrite":"Sobrescribir logos propios si existen","settings.logo.overwrite.blocked":"Hay un logo propio activo. Marca «Sobrescribir logos propios si existen» para sustituirlo por un preset de orb.","about.update.networkFail":"No se puede conectar con el servicio de actualizaciones ({host}): {detail}. Inténtalo más tarde o descarga desde Mis licencias en ready-4-it.com.","about.update.zebraCrmHashMissing":"Tu licencia es válida localmente; la entrega en línea aún se está sincronizando. Inténtalo en unos instantes o descarga desde Mis licencias en ready-4-it.com."};export const it={"lang.label":"Lingua","lang.auto":"GUI del sistema","nav.settings":"Impostazioni","nav.storage":"Archiviazione","nav.help":"Aiuto","nav.activation":"Attivazione","nav.about":"Informazioni","hud.copy.scope":"Copia ambito, versione, versione VS, derivato e progetto","hud.copy.scope.done":"Copiato","hud.copy.field.scope":"Ambito","hud.copy.field.project":"Progetto","hud.copy.field.version":"Versione","hud.copy.field.derivative":"Derivato","hud.copy.field.variation":"Variante di VS Code","hud.copy.field.vsVersion":"Versione di VS Code","hud.copy.field.content":"Contenuto","hud.copy.edit.project":"progetto","hud.copy.edit.global":"globale","settings.scope":"Ambito:","settings.scope.project":"Progetto (predefinito)","settings.scope.global":"Globale","settings.scope.hint.project":"Modifica: progetto Agents corrente (ambito Progetto)","settings.scope.hint.global":"Modifica: Globale (fallback senza override progetto)","pill.scope":"Ambito:","settings.size":"Dimensione:","settings.style":"Stile:","settings.style.stripes":"Strisce","settings.lookPreset":"Preset look","settings.reset":"Reimposta","settings.apply":"Applica","settings.close":"Chiudi","settings.boxModel":"Box model (clic = livello)","settings.inspector.border":"Inspector — Bordo","settings.inspector.border.purpose":"L’anello colorato nel modello a riquadro è la cornice della pill. Colore e spessore si applicano dopo Applica.","settings.inspector.margin.purpose":"Il margine esterno è lo spazio fuori dalla cornice.","settings.inspector.padding.purpose":"Il margine interno è lo spazio dentro la cornice, attorno all’etichetta.","settings.inspector.content.purpose":"Il contenuto è l’etichetta: carattere, riempimento e colore del testo.","settings.inspector.margin":"Inspector — Margine esterno","settings.inspector.padding":"Inspector — Margine interno","settings.inspector.content":"Inspector — Contenuto","settings.inspector.preset":"Inspector — Colore e forma","settings.borderColor":"Colore bordo","settings.borderWidth":"Spessore bordo","settings.margin":"Margine esterno (Margin)","settings.padding":"Margine interno (Padding)","settings.font":"Carattere","settings.fontSize":"Dimensione carattere","settings.fill":"Colore riempimento","settings.textColor":"Colore testo","settings.iconTitle":"Icona / Motivo","settings.mode":"Modalità:","settings.iconColor":"Colore icona:","settings.pattern":"Motivo:","settings.logo":"Logo personalizzato:","settings.logo.browse":"Sfoglia…","settings.logo.hint.empty":"Nessun logo personalizzato — opzionale via Sfoglia…","settings.logo.hint.custom":"Logo personalizzato attivo","settings.logo.hint.repo":"Il logo resta nel repo del progetto — gli aggiornamenti del file compaiono sulla pill.","settings.logo.hint.orb":"Orbe preset attivo (nessun percorso file)","settings.prefs.export":"Esporta prefs","settings.prefs.import":"Importa prefs","settings.profile.save":"Salva profilo","settings.profile.load":"Carica profilo","settings.prefs.vsProfile":"Esporta e Importa spostano un file. Salva e Carica profilo tengono una copia con nome nella cartella profili e contano nel limite. Apply lo mette sulla pill.","settings.prefs.loaded":"Caricato {name}. È in questa finestra (ambito: {scope}). Apply lo mette sulla pill.","settings.autostart":"Avvia l'HUD con Windows","settings.zebra.consent":"Consenti l’accesso di rete per il controllo aggiornamenti (disattivabile in qualsiasi momento).","settings.pro.line":"Trial/Pro: Motivo / Logo / Prefs — Loghi {logos}/{logoMax} · Profili {profiles}/{profMax} — ready-4-it.com/akc_ccc","settings.theme.hint":"Colore e forma sono separati. Pastello, Metallo, Studio e Neon valgono ognuno con Nessuna, cubo, testo, vetro o sfera. Icona/logo invariati. La pill si aggiorna solo dopo Applica.","settings.theme.bgTitle":"Sfondo (orbe → logo)","settings.theme.bgHint":"Sostituisce icona/logo — azione separata dai colori look.","storage.title":"Archiviazione / Memoria","storage.sub":"Database locale delle chat di Cursor (state.vscdb). Sola lettura della dimensione — nessuna modifica a Cursor aperto. Backup e compattazione richiedono Cursor completamente chiuso.","storage.dbPath":"Percorso del database","storage.sizeLabel":"Dimensione: {size}","storage.sizeMissing":"File del database non trovato","storage.warnMb":"Soglia di avviso (MB)","storage.warnOver":"Sopra la soglia di avviso ({mb} MB) — valuta la compattazione offline dopo aver chiuso Cursor.","storage.warnOk":"Sotto la soglia di avviso ({mb} MB).","storage.softCap":"Limite morbido di sessione (per la futura memoria MCP)","storage.archiveDir":"Cartella di archivio / backup (vuoto = ~/.cursor-archive)","storage.browse":"Sfoglia…","storage.mcpEnable":"Abilita memoria MCP (preferenza)","storage.mcpHint":"Trial/Pro: abilita la memoria MCP locale (archive_session_chunk). Free/Public: solo dimensione dell’archivio e archivi recenti.","storage.mcp.proOnly":"La memoria MCP richiede Trial/Pro (attivato). Apri ready-4-it.com/akc_ccc per passare a una versione superiore.","storage.refresh":"Aggiorna dimensione","storage.backup":"Esegui backup ora","storage.compact":"Compattazione offline…","storage.compact.confirm":"Questo ripulisce le voci grandi della cache e riduce il database. Cursor deve restare completamente chiuso. Continuare?","storage.apply":"Salva prefs","storage.openHelp":"Apri argomento della guida","storage.saved":"Prefs di archiviazione salvate.","storage.status.cursorRunning":"Cursor è in esecuzione — chiudilo completamente prima di backup o compattazione offline.","storage.status.cursorQuit":"Cursor non rilevato — backup / compattazione offline possono essere eseguiti.","storage.busy.backup":"Backup in corso…","storage.busy.compact":"Compattazione offline in corso (può richiedere minuti su database grandi)…","storage.ok.backup":"Backup completato.","storage.ok.compact":"Compattazione offline completata. Riavvia Cursor quando vuoi.","storage.err.helpers":"File di supporto archiviazione mancanti. Reinstalla il plugin.","storage.err.cursorRunning":"Chiudi prima Cursor completamente (tutti i processi) e riprova.","storage.err.exit":"Lo script di manutenzione è terminato con codice {code}. Vedi la finestra di PowerShell per i dettagli.","storage.archives.title":"Archivi CCC (sola lettura)","storage.archives.sub":"Ricerca in CCC agent_memory.db — non Unarchive della barra Cursor/VS Code. Attiva prima MCP Memory e archivia i chunk. Il ripristino resta una funzione dell’host.","storage.archives.recent":"Recenti","storage.archives.search":"Cerca","storage.archives.searchPro":"La ricerca archivi è Trial/Pro. Apertura di ready-4-it.com/akc_ccc — Free tiene solo un breve elenco Recenti.","storage.archives.empty":"Nessun archivio CCC ancora. Attiva MCP Memory, poi archive_session_chunk / riepiloghi.","storage.archives.missing":"Visualizzatore archivi mancante. Reinstalla il plugin.","storage.archives.note":"{count} voce/i · {path}","storage.archives.hint":"Indice CCC in sola lettura. Unarchive host: barra Agents → filtro Archiviati → Unarchive.","storage.quiet.title":"Silenzio / sospensione (deploy e I/O intenso)","storage.quiet.sub":"Con Silenzio attivo, l’HUD sospende le richieste di identità ai database di Cursor/VS Code, così scrivere in Agents resta fluido durante deploy o sincronizzazioni pesanti. La pill mostra il silenzio con un timer.","storage.quiet.enabled":"Abilita regole di Silenzio","storage.quiet.auto":"Sospensione automatica quando le letture dell’HUD restano lente (opzionale — può aggiungere carico)","storage.quiet.defaultSleep":"Sospensione predefinita (secondi)","storage.quiet.rules":"Regole (una per riga: nome=secondi)","storage.quiet.hint":"Esempi: deploy.exe=300  oppure  deploy.ps1=300  oppure  WinSCP.exe=180\nLa corrispondenza avviene sul nome del processo (deploy.exe) o su una sottostringa della riga di comando solo tra powershell/pwsh/cmd (deploy.ps1). Non sul titolo della finestra. Lascia disattivata la sospensione automatica se non serve. Prefs: %USERPROFILE%\\.cursor\\ccc-hud-quiet-prefs.json","storage.exp.title":"Esperimenti (opzionale)","storage.exp.sub":"Disattivato di default = pill stabile come prima. Le nuove funzioni (watch, silenzio, UIA, database glass) solo quando vuoi provarle — possono far scattare il desktop.","storage.exp.enabled":"Sblocca esperimenti","storage.exp.hudWatch":"HUD watch (segui l’identità)","storage.exp.quiet":"Regole di Silenzio / sospensione","storage.exp.uia":"Scansione UIA della barra laterale (VS Code)","storage.exp.glass":"Letture Glass / state.vscdb","storage.exp.hint":"Dopo le modifiche: riavvia l’HUD (Stop → Start). Prefs: %USERPROFILE%\\.cursor\\ccc-hud-experiments.json","storage.tab.main":"Archiviazione","storage.tab.exp":"Sperimentale","storage.tab.ext":"Esteso","storage.bak.title":"Prefs, profili e logo","storage.bak.sub":"Esporta e Importa spostano un JSON dove vuoi. Salva e Carica profilo conservano un’istantanea con nome nella cartella dei profili e contano per il limite. Il file del logo viene scritto accanto a quel JSON e ripristinato con esso. Applica scrive comunque l’aspetto sulla pill.","storage.help.bak.goal.title":"Cosa viene salvato","storage.help.bak.goal.body":"Il JSON contiene colori, forma e percorso del logo. L’immagine stessa è il file .logo accanto al JSON. Gli orb (Pastell, Metall, 3D, Neon) vengono ripristinati da quel file, o dalla grafica integrata se la copia manca.","storage.ext.title":"Esteso (MCP e manutenzione)","storage.ext.sub":"Preferenza memoria MCP (Trial/Pro), backup e compattazione offline di Cursor state.vscdb — solo con Cursor completamente chiuso.","storage.help.close":"Chiudi","storage.help.toggle":"Guida","storage.help.empty":"Nessun testo di aiuto per questa scheda.","storage.ext.recommend":"Suggerimento: chiudi Cursor completamente prima di backup o compattazione offline. Controlla la riga di stato sotto i pulsanti.","storage.help.main":"state.vscdb contiene i dati delle chat di Agents. Qui: leggere la dimensione, impostare soglia di avviso e limite morbido, scegliere la cartella di archivio, sfogliare gli archivi di sessione.\n\nPrefs: %USERPROFILE%\\.cursor\\ccc-memory-prefs.json\n\nBackup/compattazione sono sotto Esteso — chiudi prima Cursor.","storage.help.exp":"Gli esperimenti sono disattivati di default (pill stabile).\n\nSblocca l’interruttore generale, poi abilita: HUD watch, Silenzio, UIA, database glass.\nLe regole di Silenzio (deploy.exe=300) sospendono le richieste di identità.\n\nPrefs: ccc-hud-experiments.json e ccc-hud-quiet-prefs.json in %USERPROFILE%\\.cursor\\\nDopo il salvataggio: HUD Stop → Start.","storage.help.ext":"Memoria MCP (Trial/Pro): preferenza per la memoria locale di sessione.\n\nBackup: copia state.vscdb nella cartella di archivio — solo a Cursor chiuso.\n\nCompattazione offline: riduce il database dopo la chiusura di Cursor.\n\nNon compattare mai a Cursor aperto.","storage.help.main.goal.title":"Cosa fa questa scheda","storage.help.main.goal.body":"Leggere la dimensione di state.vscdb, impostare soglia di avviso e limite morbido, scegliere la cartella di archivio e sfogliare gli archivi di sessione CCC. Non compattare mai con Cursor aperto.","storage.help.main.defaults.title":"Valori predefiniti","storage.help.main.defaults.body":"Soglia di avviso: 2048 MB\nLimite morbido: 40 (futura memoria MCP)\nCartella di archivio: ~/.cursor-archive se vuota\nMemoria MCP: disattivata (preferenza Trial/Pro)\nPrefs: %USERPROFILE%\\.cursor\\ccc-memory-prefs.json","storage.help.main.do.title":"Uso quotidiano","storage.help.main.do.body":"Aggiorna ogni tanto la dimensione.\nSalva le prefs dopo le modifiche.\nUsa gli archivi recenti (Free: elenco breve; Pro: ricerca).\nBackup e compattazione sono sotto Esteso — chiudi prima Cursor.","storage.help.main.critical.title":"Quando qualcosa sembra bloccato","storage.help.main.critical.body":"Database ben oltre l’avviso + Agents si blocca → scheda Esteso.\nIl desktop scatta per colpa dell’HUD → scheda Sperimentale, disattiva Silenzio/UIA, HUD Stop → Start.","storage.help.main.steps.title":"Compattazione offline (Esteso)","storage.help.main.steps.body":"1) Chiudi Cursor (area di notifica, finché non c’è più Cursor.exe)\n2) Esteso → Compattazione offline\n3) Riavvia Cursor al termine","storage.help.exp.goal.title":"Cosa sono gli esperimenti","storage.help.exp.goal.body":"Watch + Glass tengono la pill sul progetto Agents giusto (attivi di default).\nSilenzio e UIA sono gli interruttori rischiosi — abilitali solo di proposito.","storage.help.exp.defaults.title":"Valori predefiniti","storage.help.exp.defaults.body":"Interruttore generale esperimenti: disattivato\nWatch + Glass: attivi (identità)\nSilenzio + UIA: disattivati\nFile: ccc-hud-experiments.json, ccc-hud-quiet-prefs.json","storage.help.exp.do.title":"Quando intervenire","storage.help.exp.do.body":"Uso quotidiano: lascia disattivato l’interruttore generale — Watch/Glass funzionano comunque.\nSilenzio solo con regole concrete (es. deploy.exe=300).\nUIA solo brevemente — spesso blocca il desktop.","storage.help.exp.critical.title":"Se l’IDE scatta","storage.help.exp.critical.body":"L’IDE scatta con l’HUD → disattiva Silenzio/UIA, salva le prefs, HUD Stop → Start.\nLascia disattivata la sospensione automatica di Silenzio — aggiunge carico da sola.","storage.help.exp.steps.title":"Dopo le modifiche","storage.help.exp.steps.body":"Salva le prefs nella scheda.\nHUD Stop → Start.","storage.help.ext.goal.title":"Esteso / manutenzione","storage.help.ext.goal.body":"Preferenza memoria MCP (Trial/Pro), backup e compattazione offline di state.vscdb — solo con Cursor completamente chiuso.","storage.help.ext.defaults.title":"Regole di sicurezza","storage.help.ext.defaults.body":"Il backup copia state.vscdb nella tua cartella di archivio.\nLa compattazione offline riduce il database delle chat.\nCCC rifiuta entrambi finché è attivo un processo di Cursor.","storage.help.ext.do.title":"Procedura consigliata","storage.help.ext.do.body":"Controlla la riga di stato (in esecuzione o chiuso).\nFai prima il backup se il database è enorme.\nCompatta solo dopo la chiusura; può richiedere minuti.\nRiavvia Cursor dopo la compattazione.","storage.help.ext.critical.title":"Da non fare mai","storage.help.ext.critical.body":"Non compattare mai a Cursor aperto — potresti danneggiare il database delle chat.","storage.help.ext.steps.title":"Passi della compattazione","storage.help.ext.steps.body":"1) Chiudi Cursor completamente\n2) Esteso → Compattazione offline → conferma\n3) Attendi lo stato OK\n4) Avvia di nuovo Cursor","help.nav":"Argomenti","help.drawer.toggle":"Guida","help.drawer.tip":"Guida di questa pagina","help.drawer.close":"Chiudi","help.drawer.openTopic":"Apri nella Guida","help.drawer.look.title":"Aspetto","help.drawer.look.body":"Il modello a riquadro è lo schizzo dei livelli. La mini anteprima è la pill. Colore e forma si scelgono qui, e Applica li scrive sulla pill. Icona e logo sono l’altro controllo delle Impostazioni.","help.drawer.logo.title":"Icona e logo","help.drawer.logo.body":"Pastell, Metall, 3D e Neon sostituiscono l’icona. Un logo personalizzato resta finché non spunti sovrascrivi. Esportazione e profili in Archiviazione → Backup salvano il file del logo accanto al JSON.","help.drawer.storage.title":"Archiviazione di Cursor","help.drawer.storage.body":"state.vscdb contiene i dati delle chat di Agents. Questa scheda legge la dimensione, la soglia di avviso e la cartella di archivio. Copiare o compattare quel database si fa sotto Esteso, e solo dopo aver chiuso Cursor.","help.drawer.backup.title":"Prefs e profili","help.drawer.backup.body":"Esporta sposta un file JSON dove scegli. Salva profilo conserva una copia con nome nella cartella dei profili e conta per il limite. Il file del logo viene scritto accanto al JSON e torna con l’importazione o il caricamento.","help.drawer.experiments.title":"Esperimenti","help.drawer.experiments.body":"Watch e Glass tengono la pill sulla chat Agents selezionata. Silenzio e UIA restano disattivati finché non li abiliti. Dopo una modifica, ferma l’HUD e riavvialo.","help.drawer.hygiene.title":"Backup del database","help.drawer.hygiene.body":"Esegui backup ora copia state.vscdb. Compattazione offline riduce il database. Entrambe partono solo quando Cursor è completamente chiuso.","help.drawer.activate.title":"Da Free a Pro","help.drawer.activate.body":"Ottieni CCC Pro su ready-4-it.com/akc_ccc, installa il pacchetto con licenza e attiva qui con l’hash del dispositivo e il token R4IT….","help.drawer.about.title":"Aggiornamenti","help.drawer.about.body":"Fai clic su Cerca aggiornamenti per scaricare e installare direttamente una nuova versione. Al primo avvio l’HUD chiede il permesso una sola volta.","help.topic.overview.title":"Panoramica","help.topic.overview.nav":"Panoramica","help.topic.overview.body":"AI Keep Clean Context Control Center (CCC) dà a ogni progetto in Cursor e VS Code un’identità visiva immediata.\n\nLa Pill flottante a bordo schermo mostra il progetto attivo con nome, colori, forma e logo dedicati. Fai doppio clic sulla Pill per aprire le Impostazioni.\n\nTutte le impostazioni, i loghi e i profili restano salvati in locale sul tuo computer — nessun account cloud richiesto per il lavoro quotidiano.","help.topic.start.title":"HUD, pill e avvio","help.topic.start.nav":"Avvio","help.topic.start.body":"Puoi avviare il Project HUD in tre modi:\n\n1) Estensione VS Code (AKC CCC VS)\nApri Context Control Center e fai clic su Activate. Per impostazione predefinita, l’estensione avvia l’HUD anche insieme a VS Code.\n\n2) Avvio automatico con Windows (Trial e Pro)\nSpunta «Avvia HUD con Windows» nelle Impostazioni e premi Applica.\n\n3) Avvio / arresto manuale\nSe la Pill non è ancora attiva, puoi copiare i comandi pronti per il terminale sotto Lingua e avvio.","help.topic.nav.title":"Navigazione","help.topic.nav.nav":"Navigazione","help.topic.nav.body":"In alto nella finestra dell’HUD trovi cinque sezioni:\n\nImpostazioni — colori, forma, modello a riquadro, icona/motivo e logo personalizzato.\n\nArchiviazione — dimensione del database chat, backup di prefs/profili, esperimenti opzionali e compattazione offline.\n\nAttivazione — hash dispositivo, attivazione online e token R4IT….\n\nGuida — spiegazioni brevi per ogni funzione.\n\nInfo — versione, edizione e controllo diretto degli aggiornamenti.\n\nIn alto a destra ci sono la guida della pagina corrente e il selettore della lingua.","help.topic.scope.title":"Ambito e salvataggio","help.topic.scope.nav":"Ambito","help.topic.scope.body":"In Impostazioni scegli l’ambito:\n\nProgetto (predefinito) salva solo per il progetto Agents selezionato. Globale è fallback senza prefs proprie.\n\nApplica scrive i valori e aggiorna la pill. Reimposta ripristina lo stato all’apertura. Senza Applica, le modifiche si perdono alla chiusura.","help.topic.look.title":"Look, preset e logo","help.topic.look.nav":"Look e logo","help.topic.look.body":"Il modello a riquadro mostra i livelli della Pill e la mini anteprima visualizza subito il risultato. Premi Applica per aggiornare la Pill reale.\n\nColori e forme 3D sono liberamente combinabili (Pastello, Metallo, Studio, Neon con Piatto, Cubo, Rilievo, Vetro o Sfera).\n\nLoghi e Orb (Trial/Pro): scegli un Orb integrato oppure carica la tua immagine (PNG, JPG, BMP, GIF, ICO, WebP — max 2 MB e 2048×2048). Spunta «Sovrascrivi i loghi personalizzati se presenti» per sostituire un logo attivo con un Orb.","help.topic.storage.title":"Archiviazione e manutenzione","help.topic.storage.nav":"Archiviazione","help.topic.storage.body":"Cursor salva la cronologia delle chat in locale nel file state.vscdb. Quando supera diversi gigabyte, cambiare progetto può diventare lento.\n\nLa pagina Archiviazione ha quattro schede:\n• Archiviazione — leggere la dimensione del database, impostare una soglia di avviso (predefinita 2048 MB) e scegliere la cartella di backup.\n• Backup — esportare/importare le impostazioni (incluso il logo) o salvare profili con nome.\n• Sperimentale — opzioni come la modalità Silenzio durante deploy pesanti (mette in pausa le letture in background per mantenere fluida la scrittura).\n• Esteso — eseguire il backup o la compattazione offline del database.\n\nImportante: chiudi completamente Cursor (anche nell’area di notifica) prima di eseguire backup o compattazione.","help.topic.activate.body":"Un’unica attivazione copre sia Cursor sia VS Code su questo computer.\n\nCome attivare Trial o Pro:\n\n1. Acquista CCC Pro su ready-4-it.com/akc_ccc e installa il pacchetto con licenza.\n\n2. In Attivazione fai clic su Apri attivazione online (l’hash del dispositivo è già incluso).\n\n3. Inserisci la chiave d’acquisto sul sito per ricevere il tuo token di attivazione (R4IT…).\n\n4. Incolla qui il token R4IT… e premi Usa token di attivazione.\n\nNota: AI Keep Clean (AKC) e AKC CCC sono prodotti distinti con chiavi separate.","help.topic.prefs.title":"Prefs e profili","help.topic.prefs.body":"In Archiviazione → Backup (Pro) puoi esportare e importare le impostazioni in formato JSON o salvare profili con nome. Il tuo logo personalizzato viene salvato automaticamente accanto e ripristinato al caricamento.\n\nIl numero di profili e loghi disponibili dipende dall’edizione (Free, Trial o Pro).\n\nAlla prima apertura di un progetto, CCC assegna automaticamente un’icona stabile che puoi personalizzare in qualsiasi momento.","help.topic.hudops.title":"Lingua, avvio automatico e start/stop","help.topic.hudops.nav":"Lingua e avvio","help.topic.hudops.body":"Lingua dell’HUD\n\nUsa il selettore in alto a destra. «Interfaccia di sistema» segue la lingua di Windows (inglese come riserva), oppure scegli una lingua fissa. La finestra si riapre subito.\n\nAvvio automatico con Windows (Trial e Pro)\n\nSpunta «Avvia HUD con Windows» nelle Impostazioni e premi Applica. Togli la spunta + Applica per disattivarlo.\n\nAvvio / arresto manuale\n\nSe serve, copia qui sotto i comandi pronti per il tuo terminale.","help.copy.section":"Copia percorso / comandi","help.copy.hostNote":"Suggerimento: normalmente avvii l’HUD da AKC CCC VS → Activate o con l’avvio automatico di Windows. I comandi qui sotto servono solo come alternativa manuale.","help.copy.btn":"Copia","help.copy.copied":"Copiato","help.copy.folder":"Cartella plugin","help.copy.startOne":"Start (una riga)","help.copy.stopOne":"Stop (una riga)","help.topic.privacy.nav":"Riservatezza","help.topic.privacy.body":"CCC legge localmente la selezione Cursor per associare la chat attiva al workspace. Così la pill sa quale progetto è inteso.\n\nPrefs HUD, posizione, licenza e asset restano in %USERPROFILE%\\.cursor\\ (ccc-*.json e ccc-hud-assets). CCC non ha bisogno del cloud nel quotidiano.\n\nConsegna con licenza (Trial / Pro)\n\n• Acquisto e checkout: ready-4-it.com (flusso Payhip). I termini vincolanti sono mostrati al checkout.\n• Attivazione online: ready-4-it.com riceve l’hash del dispositivo (derivato in locale da id macchina, piattaforma, hostname e un sale locale in ccc-hud-device.json) più la chiave di licenza d’acquisto per emettere un token CCC firmato (R4IT…).\n• Aggiornamenti in-app (Informazioni → Controlla aggiornamenti): il token R4IT, la versione Agents installata e l’id modulo akc_ccc vengono inviati a Streaming Zebra su api.streamingzebra.com — un servizio di consegna ready-4-it per download abilitati (URL di riscossione a breve durata, non GitHub pubblico).\n• Zebra non riceve la password Cursor né i contenuti della chat.\n\nGli aggiornamenti Free usano solo asset pubblici delle release GitHub (nessun token di licenza; il download può essere contato).\n\nLegale / privacy: ready-4-it.com/privacy · support@ready-4-it.com · Prodotto: ready-4-it.com/akc_ccc · Consegna: streamingzebra.com\n\nCCC è la sorella AKC di ready-4-it — non un prodotto a marchio Cursor.\n\nFree / Public (freemium)\n\n• Il conteggio passa da Alveos Beacon (login.alveos.eu), non da Streaming Zebra. Vengono inviati id di installazione, evento (installazione, utilizzo, aggiornamento, disinstallazione), versione, tipo di client e piattaforma. Nessuna chiave di licenza. Il consenso Zebra non copre questo conteggio.\n• I file del plugin restano su GitHub e sul Marketplace. Il VSIX Free di VS Code è un accompagnamento separato e non consegna un pacchetto Agents.","help.sketch.nav":"IMPOST.  AIUTO  ATTIV.  Info","help.sketch.content":"Contenuto / area glass","activation.title":"Usa token di attivazione","activation.sub":"Incolla qui il tuo token di attivazione CCC (R4IT…) — non la chiave d’acquisto dello shop. Un’attivazione vale per Cursor e VS Code su questo dispositivo.","activation.status":"Stato: {status} · {device}","activation.device.on":"Dispositivo attivato","activation.device.off":"Dispositivo non attivato","activation.hash":"Hash dispositivo (attivazione sito web)","activation.copyUrl":"Copia URL attivazione","activation.openOnline":"Apri attivazione online","activation.token":"Token di attivazione (R4IT…)","activation.token.maskedHint":"Accettato — viene mostrata solo una vista parziale. Fai clic sul campo per incollare un sostituto.","activation.token.editHint":"Incolla un token R4IT… completo, poi Usa token di attivazione.","activation.use":"Usa token di attivazione","activation.deactivate":"Disattiva questo dispositivo","activation.remove":"Rimuovi","activation.tier":"Livello attuale: {tier} — {hint}","activation.expiry.left":"Valido fino al {date} · {days} giorni rimanenti","activation.expiry.expired":"Scaduto il {date}","activation.expiry.none":"Nessuna data di scadenza nel token","activation.shop":"Apri shop Pro / download","activation.how.full":"CCC Pro è attivo su questo dispositivo.\n• Aggiorna in qualsiasi momento da Info → Cerca aggiornamenti.\n• Gestisci licenze e download:","activation.how.trial":"Come attivare Trial o Pro:\n1) Premi Apri attivazione online e inserisci la chiave d’acquisto.\n2) Copia il token di attivazione generato (R4IT…).\n3) Incollalo sopra e premi Usa token di attivazione.","activation.how.free":"Come passare a CCC Pro:\n1) Ottieni CCC Pro dal link qui sotto e installa il pacchetto con licenza.\n2) Premi Apri attivazione online e inserisci la chiave d’acquisto.\n3) Incolla sopra il token di attivazione ricevuto (R4IT…).","about.update":"Un clic controlla se c’è una nuova versione e la installa direttamente.","about.update.check":"Controlla aggiornamenti","about.update.legal":"Rete: Trial/Pro (attivato) inviano il token R4IT, la versione Agents installata e il modulo akc_ccc a Streaming Zebra (api.streamingzebra.com) per l’abilitazione e un link di download effimero. Free non invia alcuna licenza a Zebra. Il conteggio Free (installazione, utilizzo, aggiornamento, disinstallazione) va ad Alveos Beacon (login.alveos.eu): id di installazione, evento, versione, tipo di client e piattaforma. Il VSIX Free di VS Code è un accompagnamento separato e non consegna pacchetti Agents. Vedi Aiuto → Privacy.","about.update.consent.title":"Streaming Zebra — consenso di rete","about.update.consent.body":"La consegna Trial/Pro con licenza contatta Streaming Zebra (api.streamingzebra.com) con il token di licenza R4IT, la versione Agents installata e il modulo akc_ccc. Questo consenso copre Zebra: installazione, controllo aggiornamenti, download e disinstallazione. I download usano URL effimeri.\n\nFree/Public non è contato tramite Zebra. Quel conteggio va ad Alveos Beacon (login.alveos.eu) e non richiede questo consenso.\n\nCondizioni: streamingzebra.com/terms\nPrivacy: ready-4-it.com/privacy · streamingzebra.com/privacy","about.update.consent.checkbox":"Accetto questo uso di rete per Streaming Zebra (Trial/Pro: installazione, aggiornamento, download, disinstallazione).","about.update.consent.ok":"Accetta e continua","about.update.consent.cancel":"Annulla","about.update.consent.required":"Conferma una volta il controllo aggiornamenti (Info → Cerca aggiornamenti).","about.update.freePingOk":"Gli aggiornamenti dell’edizione gratuita arrivano tramite Marketplace o GitHub.","about.update.installConfirm":"È disponibile la versione {version}. Scaricare e installare ora?","about.update.installConfirmFree":"È disponibile l’aggiornamento gratuito {version}. Scaricare e installare ora?","about.update.installOk":"Versione {version} installata con successo.","about.update.installFail":"Installazione dell’aggiornamento non riuscita: {error}","about.update.restartAsk":"Riavviare il Project HUD per caricare la nuova versione?","about.update.upToDate":"Nessuna versione più recente. Attuale: {version}","about.update.missingCli":"Strumento di aggiornamento non trovato. Reinstalla il plugin.","about.update.missingApply":"Programma di installazione aggiornamenti non trovato. Reinstalla il plugin.","about.update.noReply":"Nessuna risposta dal controllo aggiornamenti.","about.update.checkFail":"Controllo aggiornamenti non riuscito","about.update.devHint":"Nota: il controllo ha usato DEV (CCC_ZEBRA_DEV o %USERPROFILE%\\.ccc\\zebra-dev). Per le licenze Life rimuovi il marcatore / annulla la variabile d’ambiente e riprova.","about.update.zebraTokenUnknown":"Il token di attivazione non è stato riconosciuto o è scaduto. Riattiva in Attivazione o controlla Le mie licenze su ready-4-it.com.","about.update.zebraWrongField":"Scarica una volta il pacchetto aggiornato da Le mie licenze su ready-4-it.com — la tua attivazione resta valida.","about.update.zebraWrongCredential":"Scarica una volta il pacchetto aggiornato da Le mie licenze su ready-4-it.com — la tua attivazione resta valida.","about.update.zebraDevToken":"Token di attivazione DEV: Pro è valido in locale, ma Streaming Zebra non ha ancora un record di consegna per questo token (manca l’hash del token nel CRM?). Registra il token in Zebra DEV o usa una licenza Life dallo shop.","about.update.releaseUnavailable":"Il servizio di aggiornamento è temporaneamente non disponibile. Riprova più tardi o scarica da Le mie licenze su ready-4-it.com.","about.pro.body":"Sblocca loghi personalizzati, motivi, profili e backup con CCC Pro:","about.pro.shop":"Apri shop Pro","about.legal.title":"Note legali","about.legal.terms":"Condizioni d’uso","about.legal.trademark":"Cursor, VS Code e Copilot sono marchi dei rispettivi proprietari; questo prodotto non è affiliato né approvato da essi.","about.update.checking":"Controllo in corso…","hud.menu.settings":"Impostazioni","pill.home":"Home è lo scratchbook di Cursor: una chat senza progetto.","settings.lookPreset.back":"Indietro · Bordo","settings.iconLogo":"Icona/Logo","settings.iconLogo.back":"Indietro · Bordo","settings.inspector.iconLogo":"Inspector — sostituzione icona/logo","settings.logo.recent":"Recenti:","settings.logo.recent.pick":"Il più recente","settings.logo.overwrite":"Sovrascrivi i loghi personalizzati se presenti","settings.logo.overwrite.blocked":"È attivo un logo personalizzato. Spunta «Sovrascrivi i loghi personalizzati se presenti» per sostituirlo con un preset orb.","about.update.networkFail":"Impossibile contattare il servizio di aggiornamento ({host}): {detail}. Riprova più tardi o scarica da Le mie licenze su ready-4-it.com.","about.update.zebraCrmHashMissing":"La licenza è valida in locale; la consegna online si sta ancora sincronizzando. Riprova tra poco o scarica da Le mie licenze su ready-4-it.com."};